package br.com.inframonitor.auth;
import br.com.inframonitor.auth.dto.*; import br.com.inframonitor.security.UsuarioPrincipal; import br.com.inframonitor.usuario.dto.UsuarioResponse; import jakarta.validation.Valid; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/auth") public class AuthController { private final AuthService service; public AuthController(AuthService service){this.service=service;} @PostMapping("/login") public LoginResponse login(@Valid @RequestBody LoginRequest r){return service.login(r);} @GetMapping("/me") public UsuarioResponse me(@AuthenticationPrincipal UsuarioPrincipal p){return service.me(p.id());} }
